function validate(input) {
  const [{ Tweets = [] }] = input;
  const ids = new Set(), spelling = new Map();
  for (const [user, id, date, tweet] of Tweets) {
    if (id === null) return 'Every tweet needs a tweet_id.';
    if (ids.has(id)) return `tweet_id ${id} appears twice.`;
    ids.add(id);
    // A real calendar date survives a round trip through Date unchanged.
    const day = /^\d{4}-\d{2}-\d{2}$/.test(date ?? '') ? new Date(`${date}T00:00:00Z`) : null;
    if (!day || Number.isNaN(day.getTime()) || day.toISOString().slice(0, 10) !== date) return `Tweet ${id} needs a real date like 2024-02-01.`;
    if (typeof tweet !== 'string' || tweet.split('#').length !== 2) return `Tweet ${id} must contain exactly one #.`;
    const match = /#([A-Za-z0-9]+)(?: |$)/.exec(tweet);
    if (!match) return `The hashtag in tweet ${id} must be letters and digits ending at a space or the end.`;
    const lower = match[0].trim().toLowerCase();
    if (spelling.has(lower) && spelling.get(lower) !== match[0].trim()) return `Hashtags ${spelling.get(lower)} and ${match[0].trim()} differ only in case.`;
    spelling.set(lower, match[0].trim());
  }
  return null;
}

