function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const tags = small
    ? ['#HappyDay', '#TechLife', '#WorkLife', '#Nature', '#Travel', '#Music']
    : Array.from({ length: 40 }, (_, i) => `#Topic${i}`);
  const dates = small
    ? ['2024-02-01', '2024-02-04', '2024-02-14', '2024-02-29', '2024-01-31', '2024-03-01', '2023-02-10']
    : null;
  const words = ['Great start', 'Another day', "Today's mood", 'Loving this', 'New ideas', 'Quiet morning'];
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Tweets = [];
  for (let i = 0; i < count; i++) {
    // Squaring a uniform draw favours the first tags, so counts differ but ties still happen.
    const tag = tags[Math.floor(rand() * rand() * tags.length)];
    let date;
    if (small) date = pick(dates);
    else {
      const month = rand() < 0.8 ? 2 : pick([1, 3]);
      const day = 1 + Math.floor(rand() * (month === 2 ? 29 : 31));
      date = `2024-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    }
    const where = Math.floor(rand() * 3);
    const tweet = where === 0 ? `${tag} ${pick(words)}` : where === 1 ? `${pick(words)} ${tag} again` : `${pick(words)}. ${tag}`;
    Tweets.push([100 + Math.floor(rand() * 20), i + 1, date, tweet]);
  }
  return [{ Tweets }];
}
